package com.nexuspc.order;
import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface OrderRepository extends JpaRepository<Order,Long>{List<Order> findByUserEmailIgnoreCaseOrderByCreatedAtDesc(String email); Optional<Order> findByIdAndUserEmailIgnoreCase(Long id,String email); List<Order> findAllByOrderByCreatedAtDesc(); @Query("select count(o)>0 from Order o join o.items i where lower(o.user.email)=lower(:email) and i.productId=:productId and o.status not in ('cancelled','refunded')") boolean existsPurchased(@Param("email") String email,@Param("productId") Long productId);}
